CREATE TABLE IF NOT EXISTS assessments (id TEXT PRIMARY KEY, course_id TEXT REFERENCES courses(id) ON DELETE SET NULL, title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','assigned','closed','graded')), due_at TEXT, created_by TEXT REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL, updated_at TEXT);
CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL REFERENCES assessments(id) ON DELETE CASCADE, prompt TEXT NOT NULL, question_type TEXT NOT NULL DEFAULT 'text' CHECK (question_type IN ('text','file','notebook','numeric','other')), max_points REAL, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS submissions (id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL REFERENCES assessments(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, answer_text TEXT, r2_key TEXT, status TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN ('draft','submitted','reviewed','returned')), submitted_at TEXT NOT NULL, updated_at TEXT, UNIQUE(assessment_id,user_id));
CREATE TABLE IF NOT EXISTS grades (id TEXT PRIMARY KEY, submission_id TEXT NOT NULL REFERENCES submissions(id) ON DELETE CASCADE, grader_id TEXT REFERENCES users(id) ON DELETE SET NULL, points REAL, max_points REAL, grade_label TEXT, is_published INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, published_at TEXT);
CREATE TABLE IF NOT EXISTS feedback (id TEXT PRIMARY KEY, submission_id TEXT NOT NULL REFERENCES submissions(id) ON DELETE CASCADE, author_id TEXT REFERENCES users(id) ON DELETE SET NULL, body TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'student' CHECK (visibility IN ('student','admin')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT, material_id TEXT REFERENCES materials(id) ON DELETE SET NULL, currency TEXT NOT NULL DEFAULT 'EUR', price_cents INTEGER, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','archived')), created_at TEXT NOT NULL, updated_at TEXT);
CREATE TABLE IF NOT EXISTS purchases (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, paypal_order_id TEXT UNIQUE, paypal_capture_id TEXT UNIQUE, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','verified','refunded','failed')), amount_cents INTEGER, currency TEXT, created_at TEXT NOT NULL, verified_at TEXT);
CREATE INDEX IF NOT EXISTS idx_assessments_course ON assessments(course_id);
CREATE INDEX IF NOT EXISTS idx_submissions_user ON submissions(user_id);
CREATE INDEX IF NOT EXISTS idx_purchases_user ON purchases(user_id);
